     "                         n_llis * sizeof(dw_gdma_link_list_item_t));"), 1)

# msync whole array
a = "esp_cache_msync(lli, sizeof(*lli),"
assert s.count(a) == 1, "msync"
s = s.replace(a, "esp_cache_msync(lli, n_llis * sizeof(*lli),", 1)

# ---- A2: scalar LLI setup -> chained ring ----
start = s.find("  lli_nc = priv->lli_nc;")
endm_anchor = 'dw_gdma_ll_lli_set_block_markers(lli_nc, false, true, true);\n'
endm = s.find(endm_anchor, start)
assert start > 0 and endm > 0
endm += len(endm_anchor)

loop = """  /* Circular multi-block LLI list covering the whole framebuffer.
   * Hardware auto-reloads: last descriptor chains back to the first,
   * so streaming continues without software re-arm. */

  {
    uint32_t i;
    size_t   off;

    for (i = 0, off = 0; i < n_llis; i++, off += chunk_bytes)
      {
        FAR dw_gdma_link_list_item_t *li = &priv->lli_nc[i];
        size_t   bytes = (off + chunk_bytes <= fb_size)
                         ? chunk_bytes : (fb_size - off);
        uint32_t items = (uint32_t)(bytes / 8);

        dw_gdma_ll_lli_set_src_addr(li, (uint32_t)((uintptr_t)fb + off));
        dw_gdma_ll_lli_set_dst_addr(li, MIPI_DSI_BRG_MEM_BASE);
        dw_gdma_ll_lli_set_trans_block_size(li, items);
        dw_gdma_ll_lli_set_src_master_port(li, (intptr_t)fb);
        dw_gdma_ll_lli_set_dst_master_port(li, MIPI_DSI_BRG_MEM_BASE);
        dw_gdma_ll_lli_set_src_trans_width(li, DW_GDMA_TRANS_WIDTH_64);
        dw_gdma_ll_lli_set_dst_trans_width(li, DW_GDMA_TRANS_WIDTH_64);
        dw_gdma_ll_lli_set_src_burst_items(li, DW_GDMA_BURST_ITEMS_512);
        dw_gdma_ll_lli_set_dst_burst_items(li, DW_GDMA_BURST_ITEMS_256);
        dw_gdma_ll_lli_set_src_burst_len(li, 16);
        dw_gdma_ll_lli_set_dst_burst_len(li, 16);

        /* Chain to next descriptor; last wraps back to the first */
        dw_gdma_ll_lli_set_next_item_addr(
          li, (uint32_t)(uintptr_t)&priv->lli_nc[(i + 1) % n_llis]);

        dw_gdma_ll_lli_set_block_markers(li, false, true, true);
      }
  }
"""
s = s[:start] + loop + s[endm:]

# ---- B(safe): disable software re-arm inside restart (early return) ----
rs_i = s.find("static void IRAM_ATTR esp_mipi_dsi_dma_restart")
brace = s.find("\n{\n", rs_i)
assert rs_i > 0 and brace > 0
ins_at = brace + len("\n{\n")
s = s[:ins_at] + "\n  /* Multi-block LLI ring self-perpetuates in hardware.\n" \
    "     Software re-arm here would rewrite an in-flight descriptor. */\n" \
    "  return;\n" + s[ins_at:]

open(F, "w").write(s)
print("RING_FINAL_OK")

